preConditionHook:
// A TEST OF SUPPORT THAT HOLDS. The bar's low comes within toleranceAtr ATRs of
// the most recently CONFIRMED swing low WITHOUT trading below it; mirrored, the
// bar's high tests the last swing pivot from below without exceeding it. Brooks's
// "test": the market returns to a prior swing level and fails to break it.
//
// THE ONE-SIDED FORM WINS over the symmetric band the other source states,
// because a band that extends THROUGH the level double-counts the swing-break
// rules (FailedSwingBreakoutReversal already covers the break and the recovery).
// Not BreakoutLevelRetest, which needs a prior closing breakout beyond the level
// within a wait window and allows a measured overshoot through it; here nothing
// has to have broken out and nothing may trade through. Not PriorSessionLevelTest,
// which tests a session level rather than a pivot.
//
// THE TOLERANCE IS IN ATRs, not ticks: MinMove/PriceScale are VERIFIED but the
// engine exposes no tick size to strategies, so every level tolerance in this
// corpus is scale-free. 0.25 is the source's own value.
//
// THE PIVOT SCAN IS INLINED from SwingHigh per the B-list decision, at
// Occurrence 1. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60
// min): the pivot test is MIXED -- at-or-beyond the strength OLDER bars,
// STRICTLY beyond the strength NEWER bars, and bars-ago indexing makes the
// SMALLER index the NEWER bar, so the strict half is the pk < pj loop; the
// confirmation lag is exactly strength bars, never 0 or 1, so the level is
// knowable without lookahead and during the lag the PREVIOUS pivot is reported;
// maxBarsBack is EL's Length, offsets 0..maxBarsBack-1 inclusive, and the
// neighbourhood test reaches strength bars PAST the window, so the deepest bar
// touched is maxBarsBack - 1 + strength; an empty window returns the -1
// SENTINEL, guarded because -1 as a PRICE sits under every real price; the
// comparisons carry the 2.22e-12 relational tolerance, hence el_lt / el_le /
// el_gt / el_ge. The low side's tie sense is the mirror of the measured
// high-side rule. No WFSafe_SwingLow exists, so plain EL governs.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: AtrProfitTarget's and ClimaxBar's block verbatim, including the TWO
// separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently. It stays in the hook, which the generator
// emits unconditionally, because EasyLanguage does not short-circuit and a
// stateful call inside a condition would advance on different bars in the two
// twins.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
lo1 = -1.0;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) { lo1 = low[pj]; break; }
}
hi1 = -1.0;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) { hi1 = high[pj]; break; }
}
